def max_length(lst):
    """
    Find the list of maximum length in a list of lists.

    Args:
        lst: A list of lists.

    Returns:
        A tuple containing the maximum length and the list with that length.
        If there are multiple lists with the same maximum length, returns the first one.
    """
    if not lst:
        return (0, [])

    max_len = 0
    max_list = []

    for sublist in lst:
        if len(sublist) > max_len:
            max_len = len(sublist)
            max_list = sublist

    return (max_len, max_list)
```

