def start_withp(words_list):
    """
    Return the first two words from the list that start with the letter 'p'
    (case-insensitive).

    Args:
        words_list: A list of strings, where each string can contain multiple words.

    Returns:
        A tuple of the first two words that start with 'p' (case-insensitive).
    """
    result = []
    for item in words_list:
        words = item.split()
        for word in words:
            if word.lower().startswith('p'):
                result.append(word)
                if len(result) == 2:
                    return tuple(result)
    return tuple(result)
```

