def sumofFactors(n: int) -> int:
    """
    Find the sum of even factors of a number n.
    """
    if n <= 0:
        return 0

    total = 0
    for i in range(1, n + 1):
        if n % i == 0 and i % 2 == 0:
            total += i
    return total
