def toggle_string(s: str) -> str:
    """Toggle the case of all characters in a string."""
    result = []
    for char in s:
        if char.isupper():
            result.append(char.lower())
        elif char.islower():
            result.append(char.upper())
        else:
            result.append(char)
    return ''.join(result)
