def removezero_ip(ip: str) -> str:
    parts = ip.split('.')
    cleaned = []
    for part in parts:
        # Remove leading zeroes, but keep a single '0' if the number is zero
        if part:
            # Remove leading zeros
            new_part = part.lstrip('0')
            if new_part == '':
                new_part = '0'
            cleaned.append(new_part)
        else:
            cleaned.append('0')
    return '.'.join(cleaned)
