def diff_even_odd(lst):
    """
    Find the difference of the first even and first odd number of a given list.
    Returns: first_even - first_odd
    """
    first_even = None
    first_odd = None

    for num in lst:
        if num % 2 == 0:
            first_even = num
            break

    for num in lst:
        if num % 2 != 0:
            first_odd = num
            break

    if first_even is None or first_odd is None:
        return 0

    return first_even - first_odd
```

