def is_samepatterns(patterns: list[str], words: list[str]) -> bool:
    """
    Check whether the words follow the sequence given in the patterns array.

    Each character in 'patterns' must map to exactly one word in 'words',
    and each word must map back to exactly one character (bijection).

    Args:
        patterns: A list of one-character strings representing the pattern.
        words: A list of strings representing the words to check against the pattern.

    Returns:
        True if the mapping is valid (bijective), False otherwise.
    """
    if len(patterns) != len(words):
        return False

    char_to_word = {}
    word_to_char = {}

    for char, word in zip(patterns, words):
        if char in char_to_word:
            if char_to_word[char] != word:
                return False
        else:
            char_to_word[char] = word

        if word in word_to_char:
            if word_to_char[word] != char:
                return False
        else:
            word_to_char[word] = char

    return True
```

