def find_solution(a: int, b: int, n: int) -> tuple | None:
    """
    Find integers x and y such that a*x + b*y = n.

    Returns a tuple (x, y) if a solution exists, otherwise None.
    """
    from math import gcd

    # Handle edge cases
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None

    if a == 0:
        if n % b == 0:
            return (0, n // b)
        else:
            return None

    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        else:
            return None

    # Check if solution exists
    g = gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find x0, y0 such that a*x0 + b*y0 = g
    def extended_gcd(a: int, b: int) -> tuple:
        if b == 0:
            return (a, 1, 0)
        else:
            g, x, y = extended_gcd(b, a % b)
            return (g, y, x - (a // b) * y)

    g_val, x0, y0 = extended_gcd(a, b)

    # Now a*x0 + b*y0 = g
    # We want a*x + b*y = n
    # So x = x0 * (n/g), y = y0 * (n/g)
    factor = n // g_val
    x = x0 * factor
    y = y0 * factor

    return (x, y)
```

