def find_solution(a: int, b: int, n: int):
    """
    Find integers x and y such that a*x + b*y = n.
    Returns (x, y) as a tuple, or None if no solution exists.
    """
    from math import gcd

    # Handle edge cases
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None

    if a == 0:
        # Need b*y = n
        if n % b != 0:
            return None
        return (0, n // b)

    if b == 0:
        # Need a*x = n
        if n % a != 0:
            return None
        return (n // a, 0)

    # Use extended Euclidean algorithm to find gcd and coefficients
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)

    # Check if solution exists
    if n % g != 0:
        return None

    # Scale up the solution
    multiplier = n // g
    x = x0 * multiplier
    y = y0 * multiplier

    return (x, y)
