    g = gcd(a, b)

    # A solution exists if and only if g divides n
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm (iterative)
    def extended_gcd(aa, bb):
        """Return (g, x, y) such that aa*x + bb*y = g = gcd(aa, bb)"""
        old_r, r = aa, bb
        old_s, s = 1, 0
        old_t, t = 0, 1

        while r != 0:
            quotient = old_r // r
            old_r, r = r, old_r - quotient * r
            old_s, s = s, old_s - quotient * s
            old_t, t = t, old_t - quotient * t

        return (old_r, old_s, old_t)

    g, x0, y0 = extended_gcd(a, b)

    # Scale the solution by n/g
    factor = n // g
    x = x0 * factor
    y = y0 * factor

    return (x, y)
