def is_majority(arr, n, element):
    """
    Check if the element is the majority element in the sorted array.
    The majority element occurs more than n/2 times.
    """
    # Binary search for the first occurrence of the element
    def lower_bound(arr, n, target):
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    def upper_bound(arr, n, target):
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid
        return left

    first = lower_bound(arr, n, element)

    # Check if the element exists at that position
    if first >= n or arr[first] != element:
        return False

    last = upper_bound(arr, n, element)

    count = last - first

    return count > n // 2
```

