def cal_sum(n: int) -> int:
    """
    Calculate the sum of the first n Perrin numbers.

    The Perrin sequence is defined as:
    P(0) = 3, P(1) = 0, P(2) = 2
    P(n) = P(n-2) + P(n-3) for n >= 3

    This function returns the sum of the first n Perrin numbers (from P(0) to P(n-1)).
    """
    if n <= 0:
        return 0

    # Generate Perrin numbers up to index n-1
    perrin = [0] * n
    if n > 0:
        perrin[0] = 3
    if n > 1:
        perrin[1] = 0
    if n > 2:
        perrin[2] = 2

    for i in range(3, n):
        perrin[i] = perrin[i-2] + perrin[i-3]

    return sum(perrin)
```

```python
def cal_sum(n: int) -> int:
    """
    Calculate the sum of the first n Perrin numbers.

    The Perrin sequence is defined as:
    P(0) = 3, P(1) = 0, P(2) = 2
    P(n) = P(n-2) + P(n-3) for n >= 3

    Returns the sum P(0) + P(1) + ... + P(n-1)
    """
    if n <= 0:
        return 0

    # Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3)
    perrin = {}

    def get_perrin(i):
        if i in perrin:
            return perrin[i]
        if i == 0:
            val = 3
        elif i == 1:
            val = 0
        elif i == 2:
            val = 2
        else:
            val = get_perrin(i - 2) + get_perrin(i - 3)
        perrin[i] = val
        return val

    total = 0
    for i in range(n):
        total += get_perrin(i)

    return total
```

