def is_Sub_Array(main_list: list, sub_list: list) -> bool:
    """
    Check whether sub_list is a subsequence of main_list (not necessarily contiguous).
    That is, sub_list can be obtained by deleting zero or more elements from main_list
    without changing the order of the remaining elements.
    """
    if len(sub_list) == 0:
        return True
    if len(sub_list) > len(main_list):
        return False

    main_idx = 0
    sub_idx = 0

    while main_idx < len(main_list) and sub_idx < len(sub_list):
        if main_list[main_idx] == sub_list[sub_idx]:
            sub_idx += 1
        main_idx += 1

    return sub_idx == len(sub_list)
