def find_kth(A: list, B: list, k: int) -> int:
    """
    Find the kth smallest element (1-indexed) from two sorted arrays.

    Args:
        A: First sorted array
        B: Second sorted array
        k: The position (1-indexed) of the element to find

    Returns:
        The kth smallest element
    """
    def find(A, B, k):
        if len(A) > len(B):
            return find(B, A, k)
        if len(A) == 0:
            return B[k - 1]
        if k == 1:
            return min(A[0], B[0])

        # Split k elements between A and B
        i = min(len(A), k // 2)
        j = k - i

        if A[i - 1] < B[j - 1]:
            # Discard the first i elements of A
            A = A[i:]
            k = j
        else:
            # Discard the first j elements of B
            B = B[j:]
            k = i
        return find(A, B, k)

    return find(A, B, k)
```

