def largest_subset(nums):
    if not nums:
        return 0

    sorted_nums = sorted(nums)
    n = len(sorted_nums)

    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if sorted_nums[i] % sorted_nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
