def get_coordinates(coord):
    """
    Extract all adjacent coordinates of the given coordinate tuple.
    Adjacent means within a neighborhood (including the coordinate itself).
    Works for 2D, 3D, etc. coordinates.
    """
    n = len(coord)
    result = []
    for dx in [-1, 0, 1]:
        for dy in [-1, 0, 1]:
            if n == 2:
                result.append([coord[0] + dx, coord[1] + dy])
            elif n == 3:
                for dz in [-1, 0, 1]:
                    result.append([coord[0] + dx, coord[1] + dy, coord[2] + dz])
            else:
                # For higher dimensions, generate all combinations
                from itertools import product
                for deltas in product([-1, 0, 1], repeat=n):
                    result.append([coord[i] + deltas[i] for i in range(n)])
                break
    if n != 2 and n != 3:
        # Already handled in the loop above, but restructure to avoid duplication
        from itertools import product
        result = []
        for deltas in product([-1, 0, 1], repeat=n):
            result.append([coord[i] + deltas[i] for i in range(n)])
    return result
