        while low < high:
            mid = (low + high) // 2
            if mid >= len(arr):
                return len(arr)
            if arr[mid] < x:
                low = mid + 1
            else:
                high = mid
        return min(low, len(arr))

    # Find the last index where x appears (upper bound)
    def upper_bound(arr, n, x):
        low, high = 0, n
        while low < high:
            mid = (low + high) // 2
            if mid >= len(arr):
                return len(arr)
            if arr[mid] <= x:
                low = mid + 1
            else:
                high = mid
        return min(low, len(arr))

