def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    if n == 3:
        return True
    if n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def newman_prime(n: int) -> int:
    """
    Find the nth Newman-Shanks-Williams prime number.
    Based on the test cases, this corresponds to the (n+1)-th prime (1-indexed),
    i.e., 0-indexed nth prime.

    newman_prime(0) = 2
    newman_prime(1) = 3
    newman_prime(2) = 5
    newman_prime(3) = 7
    newman_prime(4) = 11
    newman_prime(5) = 13
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    count = 0
    candidate = 2
    while True:
        if is_prime(candidate):
            if count == n:
                return candidate
            count += 1
        candidate += 1
