def start_withp(words_list):
    """
    Return the first two words from a list of strings that start with the letter 'p'
    (case-insensitive).

    Each element in words_list is a string that may contain multiple words.
    Words are extracted by splitting each string on whitespace.

    Args:
        words_list: A list of strings.

    Returns:
        A tuple containing up to two words that start with 'p' (case-insensitive).
    """
    result = []
    for item in words_list:
        words = item.split()
        for word in words:
            if word.lower().startswith('p'):
                result.append(word)
                if len(result) == 2:
                    return tuple(result)
    return tuple(result)
