def sum_of_digits(numbers):
    total = 0
    for num in numbers:
        # If the element is a list, recurse into it
        if isinstance(num, list):
            total += sum_of_digits(num)
        elif isinstance(num, (int, float)):
            # For integers and floats, sum the digits (ignoring sign and decimal point)
            s = str(abs(num))
            for ch in s:
                if ch.isdigit():
                    total += int(ch)
        elif isinstance(num, str):
            # For strings, sum only the digit characters
            for ch in num:
                if ch.isdigit():
                    total += int(ch)
    return total
