            abs_num = abs(num)
            for ch in str(abs_num):
                if ch.isdigit():
                    total += int(ch)
        elif isinstance(num, str):
            for ch in num:
                if ch.isdigit():
                    total += int(ch)
        elif isinstance(num, (list, tuple)):
            # Recursively process nested sequences
            total += sum_of_digits(list(num))
    return total
